/** `status` of an envelope. */
export type envelope_Status = 'ok' | 'needs_confirmation' | 'error';

/** One object change of a committed (or dry-run) transaction (10 §2.6, 11 §7.2). */
export interface envelope_ChangeRecord {
  /** Object id (compound for container-local ids). */
  id: string;
  /** Object type. */
  type: string;
  /** `created`, `modified` or `deleted`. */
  op: string;
  /** The object's `rev` after the transaction (the `documentRev` it would get for a dry run). */
  rev: number | bigint;
  /** Parent (created and deleted objects). */
  parentId?: string | null;
  /** Position in the parent's collection (created objects). */
  index?: number | bigint | null;
  /** Own-view RFC 6902 patch with `oldValue` (modified objects). */
  patch?: unknown[] | null;
}

/** The undo step a transaction created. */
export interface envelope_UndoRef {
  /** Step id (`u-<n>`). */
  stepId: string;
  /** Label. */
  label: string;
}

/** A warning (11 §6.3, §10): same code space as errors, never aborts. */
export interface envelope_Warning {
  /** Code. */
  code: string;
  /** Message. */
  message: string;
  /** Affected objects. */
  objectIds?: string[];
}

/** A typed command error in the `{code, message, details, hint?}` wire form (11 §10). */
export interface envelope_CommandError {
  /** Stable dotted code `area.reason`. */
  code: string;
  /** Human-readable message. */
  message: string;
  /** Structured details (boxed: the error travels in every `Result` of the command path, so it stays small). */
  details: unknown;
  /** How to fix the call, where known. */
  hint?: string | null;
}

/** The command result envelope (11 §7.2), also the shape of each batch step. */
export interface envelope_root {
  /** `ok`, `needs_confirmation` or `error`. */
  status: envelope_Status;
  /** Command-specific result (per its result schema). */
  result?: unknown;
  /** What was actually targeted (P4). */
  targets?: unknown;
  /** Changed objects (capped at [`crate::CHANGES_CAP`]). */
  changes: envelope_ChangeRecord[];
  /** `true` when `changes` was capped; read the rest with `doc.diff` from `changesSince`. */
  changesTruncated?: boolean;
  /** Revision to pass to `doc.diff` when `changes` was capped. */
  changesSince?: number | bigint | null;
  /** The undo step created. */
  undo?: envelope_UndoRef | null;
  /** Warnings. */
  warnings: envelope_Warning[];
  /** `documentRev` after the call (`null` with no project). */
  documentRev?: number | bigint | null;
  /** The error of a failed call. */
  error?: envelope_CommandError | null;
  /** `true` for a dry run. */
  dryRun?: boolean;
  /** Batch step envelopes. */
  steps?: envelope_root[] | null;
}

/** Export format. */
export type agent_activity_export_ActivityFormat = 'jsonl' | 'batch';

/** Export conflict policy. */
export type agent_activity_export_ExportOnExists = 'fail' | 'overwrite' | 'rename';

/** `agent.activity.export` parameters. */
export interface agent_activity_export_params {
  /** Target path. */
  path: string;
  /** Format. */
  format?: agent_activity_export_ActivityFormat;
  /** Conflict policy. */
  onExists?: agent_activity_export_ExportOnExists;
}

/** An activity entry a replayable batch leaves out. */
export interface agent_activity_export_Omitted {
  /** The entry's sequence number. */
  seq: number | bigint;
  /** Its tool. */
  tool: string;
  /** Its command. */
  command_id: string;
  /** `notCompleted` (it committed nothing: an error, or a confirmation that was not given), `cachedRetry` (a `requestId` retry answered from the cache), `dryRun` (it changed nothing), `readOnly` (a query), `notACommand` (a discovery tool such as `list_commands`), `redacted` (inline data replaced by its hash). */
  reason: string;
}

/** `{path, entries, omitted?}`. */
export interface agent_activity_export_result {
  /** File written. */
  path: string;
  /** Entries. */
  entries: number;
  /** `format: "batch"`: the entries left out of the replayable batch, with the reason (C14-R1-15); empty otherwise. */
  omitted: agent_activity_export_Omitted[];
}

/** `agent.activity.list` parameters. */
export interface agent_activity_list_params {
  /** Session. */
  sessionId?: string | null;
  /** Since (ISO 8601). */
  since?: string | null;
  /** Maximum entries. */
  limit?: number | null;
}

export type agent_activity_list_result = ({
  /** Sequence number (per process). */
  seq: number | bigint;
  /** When the call finished. */
  time: string;
  /** Session id. */
  sessionId: string;
  /** Client name. */
  client: string;
  /** MCP tool (or `batch-script`). */
  tool: string;
  /** Command id (`batch` for batches). */
  commandId: string;
  /** Parameters, with inline media replaced by a hash. */
  params: unknown;
  /** `ok`, `needs_confirmation` or `error`. */
  status: string;
  /** Error code. */
  errorCode?: string | null;
  /** The error's `details.reason`, or that of the step error a `batch.stepFailed` wraps (`"cancelled"`: its caller cancelled the request; C34-R4-01). */
  errorReason?: string | null;
  /** Undo step. */
  undoStepId?: string | null;
  /** Changed objects. */
  changedCount: number | bigint;
  /** The call was a dry run (it changed nothing; a replay must not turn it into an edit; C14-R1-15). */
  dryRun?: boolean;
  /** The answer came from the `requestId` cache: a retry of an earlier call, which executed nothing (C14-R2-03). */
  cachedRetry?: boolean;
  /** A batch: the indexes of the steps it committed (all or none for an atomic batch; the successful ones of a sequential batch, which commits step by step; C14-R2-02). */
  committedSteps?: (number | bigint)[] | null;
  /** Document revision after the call. */
  documentRev?: number | bigint | null;
  /** Duration. */
  durationMs: number | bigint;
})[];

