/** Pivot application of pegs and skeletons (05 §2.3). */
export type fx_get_ApplyPivotTo = 'rotation' | 'scaling' | 'both';

/** A 2-D affine transform as axes and origin (06 §3.4 shadow transform). */
export interface fx_get_AxesTransform {
  /** Image of the x axis. */
  xAxis: fx_get_Point2;
  /** Image of the y axis. */
  yAxis: fx_get_Point2;
  /** Origin (fields). */
  origin: fx_get_Point2;
}

/** Static parameters of a particle block (06 §3.8.3). Frames are absolute scene frames. */
export interface fx_get_BlockStatic {
  /** Background drawn behind the particles. */
  background: fx_get_ParticleBackground;
  /** First simulated frame (≤ firstFrame, ≥ firstFrame − 999; may be < 1 for pre-roll). */
  simulationStart: number;
  /** First displayed frame. */
  firstFrame: number;
  /** Frames the block lasts, ≥ 1. */
  duration: number;
  /** Particle cap (≤ 3000; 50 for fog and cloud). */
  maxParticles: number;
  /** Lifetime in frames: −1 (unlimited) or 0–512. */
  lifetimeFrames: number;
  /** Fade particles out. */
  fade: boolean;
  /** Region width 0–1999 particle units. */
  areaWidth: number;
  /** Region height 0–1999. */
  areaHeight: number;
  /** Region depth 0–1999. */
  areaDepth: number;
  /** Floor height 0–1999. */
  floorLevel: number;
}

/** Blur parameters (06 §3.5). */
export interface fx_get_BlurParams {
  /** Uniform (true) or directional (false) blur (static). */
  radial: boolean;
  /** Radius 0–100 output pixels (animatable). */
  radius: number;
  /** Motion-blur direction 0–360 degrees (animatable). */
  angle: number;
}

/** Bone block (10 §4.6, 05 §13.1–§13.3). */
export interface fx_get_BoneBlock {
  /** Rest pose. */
  rest: fx_get_BoneRest;
  /** Zone of influence. */
  influence: fx_get_BoneInfluence;
}

/** Zone of influence of a bone (05 §13.3). */
export interface fx_get_BoneInfluence {
  /** Infinite or elliptical. */
  type: fx_get_InfluenceType;
  /** Length radius (fields). */
  lengthRadius: number;
  /** Width radius (fields). */
  widthRadius: number;
  /** Explicit region polygon, or `null`. */
  region: fx_get_Point2[] | null;
}

/** Rest pose of a bone (05 §13.1). */
export interface fx_get_BoneRest {
  /** X (fields). */
  x: number;
  /** Y (fields). */
  y: number;
  /** Rotation (degrees). */
  rotation: number;
  /** Length (fields), > 0.01. */
  length: number;
}

/** Camera block (10 §4.6, 05 §12.3). */
export interface fx_get_CameraBlock {
  /** Static or dynamic FOV. */
  fovMode: fx_get_FovMode;
  /** FOV 1–179 degrees (default 2·atan(0.375) ≈ 41.1121, 05 §2.7). */
  fov: number;
}

/** An animation channel (10 §4.12). The `name` is the channel id (`rotation`, `scale.x`, …, or an effect parameter id) and equals its key in the element's `channels` map. A 1-D channel has `curveType` and `keys`; the motion-path channel `position` has `points` instead. */
export interface fx_get_Channel {
  /** Immutable ID. */
  id: fx_get_Id;
  /** Always `channel`. */
  type: 'channel';
  /** Revision of the last change. */
  rev: number | bigint;
  /** The channel id. */
  name: string;
  /** 1-D channels: curve type. */
  curveType?: fx_get_CurveType;
  /** 1-D channels: keys sorted by frame, at least one. */
  keys?: (fx_get_Key | fx_get_KeyStub)[];
  /** Motion path: points in path order; first and last are keyframes. */
  points?: (fx_get_MotionPoint | fx_get_MotionPointStub)[];
  /** Free-form metadata. */
  meta?: Record<string, unknown>;
  /** Extension data. */
  ext?: fx_get_Ext;
  /** Canonical path (10 §2.4). */
  path?: string;
}

/** A `fx_get_Channel` reduced to its stub (10 §2.2). */
export interface fx_get_ChannelStub {
  id: fx_get_Id;
  type: 'channel';
  name?: string;
}

/** Clipping parameters (06 §3.3). */
export interface fx_get_ClippingParams {
  /** Draw children outside the mask instead of inside. */
  inverted: boolean;
}

/** sRGB colour with straight alpha, #RRGGBBAA (written upper case; #RRGGBB accepted on input). */
export type fx_get_Colour = string;

/** Colour Transform parameters (06 §3.2). */
export interface fx_get_ColourTransformParams {
  /** Red multiplier 0–1 (animatable). */
  multRed: number;
  /** Green multiplier 0–1 (animatable). */
  multGreen: number;
  /** Blue multiplier 0–1 (animatable). */
  multBlue: number;
  /** Alpha multiplier 0–1 (animatable). */
  multAlpha: number;
  /** Red offset −255…255 (animatable). */
  addRed: number;
  /** Green offset −255…255 (animatable). */
  addGreen: number;
  /** Blue offset −255…255 (animatable). */
  addBlue: number;
  /** Alpha offset −255…255 (animatable). */
  addAlpha: number;
  /** Composite the sub-tree first (static). */
  flatten: boolean;
}

/** Curve type of a 1-D channel (05 §10.3). */
export type fx_get_CurveType = 'spline' | 'interpolation' | 'velocityBased';

/** Drop Shadow parameters (06 §3.4; all static). */
export interface fx_get_DropShadowParams {
  /** How a parent Colour Transform applies. */
  parentColourTransformMode: fx_get_ParentColourTransformMode;
  /** Shadow colour (alpha ignored). */
  colour: fx_get_Colour;
  /** Opacity percent 0–100. */
  opacity: number;
  /** Draw only the shadow. */
  hideElements: boolean;
  /** Shadow transform in effect-local space. */
  transform: fx_get_AxesTransform;
}

/** A dynamic block parameter: a constant `{value}` or `{keyframes}` (06 §8.4). */
export type fx_get_DynamicParam = {
  /** The value. */
  value: number;
} | {
  /** Keyframes sorted by frame, at least one. */
  keyframes: fx_get_FrameValue[];
};

/** Easing presets (05 §10.4). */
export type fx_get_Easing = 'constant' | 'linear' | 'easeInOut' | 'fastInOut' | 'extremeEaseInOut' | 'extremeFastInOut' | 'slowAcceleration' | 'slowDeceleration';

/** An element of a scene (10 §4.5–§4.7). Stored in `scenes/<sceneId>/elements/<elementId>.json`. */
export interface fx_get_Element {
  /** Immutable ID. */
  id: fx_get_Id;
  /** Always `element`. */
  type: 'element';
  /** Revision of the last change. */
  rev: number | bigint;
  /** Unique in the scene. */
  name: string;
  /** Element type; read-only except through conversion commands. */
  elementType: fx_get_ElementType;
  /** Non-cell elements: first frame of the bar (persisted). Cell-based elements: derived from the exposure (query results only). */
  start?: number;
  /** Non-cell elements: length of the bar (absent for cell-based elements: derived). */
  duration?: number;
  /** Loop count ≥ 1; 1 = not looped. */
  loops: number;
  /** Count or fill. */
  loopType: fx_get_LoopType;
  /** Cycle or offset. */
  positionLoop: fx_get_PositionLoop;
  /** `fill` loops: the cycle length in frames, which `duration` and `loops` cannot express when the last cycle is partial (SI-089). */
  cycleLength?: number;
  /** Composite role. */
  role: fx_get_Role;
  /** Deformable by a skeleton. */
  deformable: boolean;
  /** Shown in scene views, playback and export. */
  visibleInScene: boolean;
  /** Cell-based elements: shown in the Exposure Sheet and Drawing View. */
  visibleInXsheet?: boolean;
  /** Locked in scene views. */
  locked: boolean;
  /** Timeline display state of parents. */
  collapsed: boolean;
  /** Marker colour; `null` = category default. */
  markerColour: fx_get_Colour | null;
  /** Background colour; `null` = category default. */
  backgroundColour: fx_get_Colour | null;
  /** Element note (≤ 10 000 characters). */
  note?: string;
  /** Exposure Sheet column width, 20–1000 view pixels. */
  columnWidth: number;
  /** Cell-based: the drawing bank (shared by clones). */
  drawingBankId?: fx_get_Id;
  /** Cell-based: canonical exposure runs from frame 1. */
  exposure?: ([fx_get_Id | null, number])[];
  /** Cell-based: notes by frame. */
  cellNotes?: Record<string, string>;
  /** Image elements: import options (section 09; SI-008). */
  importOptions?: Record<string, unknown>;
  /** Sound: streamed playback. */
  streamed?: boolean;
  /** Sound: the Exposure Sheet shows mouths. */
  showMouthShapes?: boolean;
  /** Sound: placements sorted by `startFrame`, non-overlapping. */
  placements?: (fx_get_SoundPlacement | fx_get_SoundPlacementStub)[];
  /** Sound: one mapping per mapped drawing element. */
  lipSyncMappings?: fx_get_LipSyncMapping[];
  /** Media: sequences, non-overlapping. */
  sequences?: (fx_get_MediaSequence | fx_get_MediaSequenceStub)[];
  /** Transformable elements: the static transform. */
  transform?: fx_get_Transform;
  /** Pegs: export grouping. */
  exportGroup?: fx_get_ExportGroup;
  /** Cameras: FOV settings. */
  camera?: fx_get_CameraBlock;
  /** Skeletons: display and deformation settings. */
  skeleton?: fx_get_SkeletonBlock;
  /** Bones: rest pose and influence. */
  bone?: fx_get_BoneBlock;
  /** Effect parameter elements: the slot. */
  slot?: fx_get_ParamSlot;
  /** Effects: static parameter values (exact shape per `elementType`). */
  params?: Record<string, unknown>;
  /** Particle effects: blocks, consecutive. */
  blocks?: (fx_get_ParticleBlock | fx_get_ParticleBlockStub)[];
  /** Animated channels by channel id. */
  channels?: Record<string, fx_get_Channel | fx_get_ChannelStub>;
  /** Creation time. */
  createdAt: fx_get_Timestamp;
  /** Free-form metadata. */
  meta?: Record<string, unknown>;
  /** Extension data. */
  ext?: fx_get_Ext;
  /** Canonical path (10 §2.4). */
  path?: string;
  parentId?: fx_get_Id | null;
  childIds?: fx_get_Id[];
  depth?: number;
  timelineIndex?: number;
  xsheetIndex?: number | null;
  cloneGroupId?: fx_get_Id | null;
  cloneIds?: fx_get_Id[];
  drawingCount?: number;
  hiddenByParent?: boolean;
  effectiveMarkerColour?: fx_get_Colour;
}

/** A `fx_get_Element` reduced to its stub (10 §2.2). */
export interface fx_get_ElementStub {
  id: fx_get_Id;
  type: 'element';
  name?: string;
}

/** Element types (10 §4.5). The 04 read model reports this value as `type`; the object model uses `elementType` (design decision D6). */
export type fx_get_ElementType = 'drawing' | 'annotation' | 'image' | 'sound' | 'media' | 'peg' | 'camera' | 'skeleton' | 'bone' | 'effectParameter' | 'colourTransform' | 'clipping' | 'dropShadow' | 'blur' | 'shake' | 'particleNature' | 'particleImpact';

/** A gain point of a placement envelope (07 §9.5). */
export interface fx_get_EnvelopePoint {
  /** Time within the source (seconds). */
  time: number;
  /** Left gain 0–1. */
  left: number;
  /** Right gain 0–1. */
  right: number;
}

/** Export-group block of pegs (05 §8.2, 09). */
export interface fx_get_ExportGroup {
  /** Group the subtree on vector export. */
  groupOnVectorExport: boolean;
  /** Add a composite for the export group. */
  addComposite: boolean;
}

/** Extension data keyed by reverse-DNS namespace; unknown namespaces are preserved verbatim. */
export type fx_get_Ext = Record<string, unknown>;

/** Camera FOV mode (05 §12.3). */
export type fx_get_FovMode = 'static' | 'dynamic';

/** An inclusive frame range `{from, to}` (10 §1.1). */
export interface fx_get_FrameRange {
  /** First frame (1-based). */
  from: number;
  /** Last frame (inclusive). */
  to: number;
}

/** A `{frame, value}` keyframe of a dynamic block parameter. */
export interface fx_get_FrameValue {
  /** Absolute scene frame. */
  frame: number;
  /** Value. */
  value: number;
}

/** Handle mode. */
export type fx_get_HandleMode = 'smooth' | 'broken';

/** A handle offset `{dt, dv}` (05 §10.3). */
export interface fx_get_HandleOffset {
  /** Frame offset. */
  dt: number;
  /** Value offset. */
  dv: number;
}

