/** A workspace layout on the wire (01 §12.4 `Layout`): the normal arrangement's fields plus the separate full-screen arrangement (01 §5.6). Panels not mentioned are hidden. */
export interface workspace_layout_set_result {
  /** The central view. */
  centralPanel: string;
  /** Corner ownership. */
  corners: workspace_layout_set_Corners;
  /** Dock areas. */
  docks: workspace_layout_set_Docks;
  /** Floating panels. */
  floating?: workspace_layout_set_Floating[];
  /** Tool palettes. */
  toolPalettes?: workspace_layout_set_ToolPalette[];
  /** Main toolbar. */
  mainToolbar: workspace_layout_set_MainToolbar;
  /** Full-screen arrangement (same shape without `fullScreen`). */
  fullScreen: workspace_layout_set_Arrangement;
}

/** No parameters. */
export type workspace_list_params = Record<string, unknown>;

/** A workspace as listed by `workspace.list`. */
export interface workspace_list_WorkspaceEntry {
  /** Name. */
  name: string;
  /** Built in (cannot be deleted). */
  builtIn: boolean;
  /** The current arrangement differs from the stored one (current workspace only). */
  modified: boolean;
  /** Position in the list (1-based). */
  position: number | bigint;
  /** The current workspace. */
  current: boolean;
}

export type workspace_list_result = workspace_list_WorkspaceEntry[];

/** `workspace.rename` parameters. */
export interface workspace_rename_params {
  /** Current name. */
  name: string;
  /** New name. */
  newName: string;
}

/** `{name}`. */
export interface workspace_rename_result {
  /** Workspace name. */
  name: string;
}

/** `workspace.reset` parameters. */
export interface workspace_reset_params {
  /** Built-in workspace (default: current). */
  name?: string | null;
  /** Every built-in workspace. */
  all?: boolean;
  /** Select it afterwards. */
  select?: boolean;
}

/** `{reset}`. */
export interface workspace_reset_result {
  /** Reset workspaces. */
  reset: string[];
}

/** `{name?}` parameters. */
export interface workspace_save_params {
  /** Workspace name (default: the current arrangement). */
  name?: string | null;
}

/** `{name}`. */
export interface workspace_save_result {
  /** Workspace name. */
  name: string;
}

/** `workspace.select` parameters. */
export interface workspace_select_params {
  /** Workspace name. */
  name: string;
  /** Save the current arrangement into the current workspace first (default: the preference `general.workspace.autoSave`, whose default is on, 01 §7; preferences arrive in M4). */
  saveCurrent?: boolean | null;
}

/** `{name}`. */
export interface workspace_select_result {
  /** Workspace name. */
  name: string;
}

export interface xsheet_columnWidth_set_params {
  /** object ID or path reference (10 §3) */
  elementId?: string;
  width?: number;
  reset?: boolean;
}

export interface xsheet_columnWidth_set_result {
  /** (elementId → int) */
  widths: Record<string, number | bigint>;
}

export interface xsheet_currentCell_set_params {
  /** object ID or path reference (10 §3) */
  elementId: string;
  frame: number | bigint;
}

export interface xsheet_currentCell_set_result {
  /** object ID or path reference (10 §3) */
  elementId: string;
  frame: number | bigint;
}

export interface xsheet_display_set_params {
  thumbnails?: boolean;
  exposureText?: boolean;
  elementNames?: boolean;
  notes?: boolean;
}

export interface xsheet_display_set_result {
  thumbnails: boolean;
  exposureText: boolean;
  elementNames: boolean;
  notes: boolean;
}

/** Optional parts of the sheet. */
export type xsheet_exposures_get_Include = 'notes' | 'mouths' | 'thumbnails';

/** `xsheet.exposures.get` parameters. */
export interface xsheet_exposures_get_params {
  /** Scene (default: the current scene). */
  sceneId?: string | null;
  /** Only these columns (default: every cell-based element, Exposure Sheet order). */
  elementIds?: string[] | null;
  /** First frame of the window. */
  from?: number | bigint;
  /** Last frame of the window (default: the scene length). */
  to?: number | bigint | null;
  /** Optional parts: `notes`, `mouths`, `thumbnails`. */
  include?: xsheet_exposures_get_Include[] | null;
}

/** One column. */
export interface xsheet_exposures_get_ColumnOut {
  /** The element. */
  elementId: string;
  /** Its name. */
  name: string;
  /** Its type. */
  elementType: string;
  /** Shown in the Exposure Sheet. */
  visible: boolean;
  /** Exposed runs (drawing, image, annotation and media columns). */
  exposures?: xsheet_exposures_get_Run[] | null;
  /** Cell notes in the window (with `include: ["notes"]`). */
  notes?: xsheet_exposures_get_Note[] | null;
  /** Sound clips (sound columns). */
  clips?: xsheet_exposures_get_Clip[] | null;
  /** Mouth runs (sound columns, with `include: ["mouths"]`). */
  mouths?: xsheet_exposures_get_Mouth[] | null;
  /** Thumbnails by drawing ID (with `include: ["thumbnails"]`). */
  thumbnails?: Record<string, unknown> | null;
}

/** One exposed run. */
export interface xsheet_exposures_get_Run {
  /** Drawing name (media: the media item's name). */
  drawing: string;
  /** Drawing ID (media: the sequence ID). */
  drawingId: string;
  /** First frame inside the window. */
  from: number;
  /** Last frame inside the window. */
  to: number;
  /** The run continues outside the window: `before`, `after` or `both`. */
  continues?: string | null;
}

/** One cell note. */
export interface xsheet_exposures_get_Note {
  /** Frame. */
  frame: number;
  /** Text. */
  text: string;
}

/** One sound clip. */
export interface xsheet_exposures_get_Clip {
  /** The placement. */
  clipId: string;
  /** The sound asset's name. */
  file: string;
  /** First frame inside the window. */
  from: number;
  /** Last frame inside the window. */
  to: number;
  /** Continuation outside the window. */
  continues?: string | null;
}

/** One mouth run. */
export interface xsheet_exposures_get_Mouth {
  /** `A`–`G` or `X`. */
  mouth: string;
  /** First frame. */
  from: number;
  /** Last frame. */
  to: number;
}

/** The exposure-sheet object (04 §17.2). */
export interface xsheet_exposures_get_result {
  /** The scene. */
  sceneId: string;
  /** Sheet revision. */
  rev: number | bigint;
  /** Scene length. */
  sceneLength: number;
  /** Window start. */
  from: number;
  /** Window end. */
  to: number;
  /** Columns in Exposure Sheet order. */
  columns: xsheet_exposures_get_ColumnOut[];
}

/** One column to write. */
export interface xsheet_exposures_set_ColumnIn {
  /** The element. */
  elementId: string;
  /** Window start (default 1). */
  from?: number | bigint | null;
  /** Window end (default: the later of the last run's end and the element's last exposed frame). */
  to?: number | bigint | null;
  /** Runs, sorted and non-overlapping, inside the window; frames not covered become blank. */
  exposures: xsheet_exposures_set_RunIn[];
}

/** One run to write. */
export interface xsheet_exposures_set_RunIn {
  /** Drawing name in the column's bank. */
  drawing?: string | null;
  /** Drawing ID (or path). */
  drawingId?: string | null;
  /** First frame. */
  from: number | bigint;
  /** Last frame. */
  to: number | bigint;
}

/** `xsheet.exposures.set` parameters. */
export interface xsheet_exposures_set_params {
  /** Scene (default: the current scene); every column must belong to it. */
  sceneId?: string | null;
  /** Columns to write. */
  columns: xsheet_exposures_set_ColumnIn[];
  /** Create empty drawings for unknown names (drawing and annotation columns). */
  createMissingDrawings?: boolean;
  /** The sheet revision the edit is based on (`xsheet.revisionMismatch` otherwise). */
  expectRev?: number | bigint | null;
  /** Validate and return the diff without applying it. */
  dryRun?: boolean;
}

/** A change of one element's cells: `{elementId, from, to}`. */
export interface xsheet_exposures_set_CellChange {
  /** The element. */
  elementId: string;
  /** First changed frame. */
  from: number;
  /** Last changed frame. */
  to: number;
}

/** A created drawing. */
export interface xsheet_exposures_set_Created {
  /** The column. */
  elementId: string;
  /** The drawing. */
  drawingId: string;
  /** Its name. */
  name: string;
}

/** `{rev, sceneLength, changed, createdDrawings}`. */
export interface xsheet_exposures_set_result {
  /** The sheet revision after the change. */
  rev: number | bigint;
  /** The scene length after the change. */
  sceneLength: number;
  /** Changed windows per column. */
  changed: xsheet_exposures_set_CellChange[];
  /** Drawings created by `createMissingDrawings`. */
  createdDrawings: xsheet_exposures_set_Created[];
}

